class Solution:
    def chain(self, A: str, B: str) -> str:
        A, B = A[0], B[0]
        res = []
        while A:
            if A[-1] == B:
                res.append(A[-1])
            else:
                res.append(A[-1])
            A.pop()
        res.append(B)
        return ','.join(res)
